import { LightConfig } from "type";
import { gameConfig } from "game/config";
import { GameScene } from "../GameScene";

export class Light {
  constructor(scene: GameScene, config: LightConfig) {
    const {
      x,
      y,
      color = gameConfig.colors.defaultLight,
      intensity = 1.5,
      radius = 300,
      id,
      positionType,
    } = config;

    let xCoordinate = x,
      yCoordinate = y;

      if (positionType === 'tile') {
        const object = scene.tilemap?.getTileAtWorldXY(
          x,
          y,
          true,
          scene.camera,
          "objects",
        );

      }

    this.light = scene.lights
      .addLight(x, y, radius, color)
      .setIntensity(intensity);

    this.id = id;
  }

  light: Phaser.GameObjects.Light;
  id?: string;
}
